import { z } from "zod";

import { prisma } from "../lib/prisma.js";
import { AppError } from "../utils/app-error.js";

// Product ids are cuids; order ids are UUIDs generated by the Order service.
const productIdSchema = z.string().trim().min(1).max(64).regex(/^[A-Za-z0-9_-]+$/, "Invalid id");

const itemsSchema = z.array(
    z.object({
        productId: productIdSchema,
        quantity: z.number().int().min(1).max(999)
    })
).min(1).max(100);

const validateSchema = z.object({ items: itemsSchema });
const confirmSchema = z.object({ orderId: z.string().uuid(), items: itemsSchema });

function parse(schema, value) {
    const result = schema.safeParse(value);
    if (result.success) return result.data;

    const error = new AppError(400, "The request contains invalid fields.", "VALIDATION_ERROR");
    error.details = result.error.issues.map((issue) => ({
        field: issue.path.join("."),
        message: issue.message
    }));
    throw error;
}

// POST /internal/stock/validate
// Returns current price and available stock. Order uses these values; it never trusts the browser.
export async function validateStock(req, res, next) {
    try {
        const { items } = parse(validateSchema, req.body);

        const products = await prisma.product.findMany({
            where: { id: { in: items.map((item) => item.productId) }, isActive: true },
            select: { id: true, name: true, price: true, stock: true }
        });
        const byId = new Map(products.map((product) => [product.id, product]));

        const problems = [];
        for (const item of items) {
            const product = byId.get(item.productId);
            if (!product) {
                problems.push({ productId: item.productId, reason: "PRODUCT_NOT_FOUND" });
            } else if (product.stock < item.quantity) {
                problems.push({ productId: item.productId, reason: "INSUFFICIENT_STOCK" });
            }
        }

        res.status(200).json({
            data: {
                valid: problems.length === 0,
                items: products.map((product) => ({
                    productId: product.id,
                    name: product.name,
                    unitPrice: product.price.toFixed(2),
                    availableQuantity: product.stock
                })),
                problems
            }
        });
    } catch (error) {
        next(error);
    }
}

// POST /internal/stock/confirm
// Deducts stock after a successful payment. Atomic (all items or none), never negative,
// and idempotent per orderId, so a retried call cannot deduct twice.
export async function confirmStock(req, res, next) {
    try {
        const { orderId, items } = parse(confirmSchema, req.body);
        // Fixed order avoids deadlocks between concurrent confirmations.
        const sorted = [...items].sort((a, b) => a.productId.localeCompare(b.productId));

        let status;
        try {
            status = await prisma.$transaction(async (tx) => {
                const already = await tx.stockConfirmation.findUnique({ where: { orderId } });
                if (already) return "ALREADY_CONFIRMED";

                await tx.stockConfirmation.create({ data: { orderId } });

                for (const item of sorted) {
                    const { count } = await tx.product.updateMany({
                        where: { id: item.productId, isActive: true, stock: { gte: item.quantity } },
                        data: { stock: { decrement: item.quantity } }
                    });
                    if (count !== 1) {
                        // Throwing rolls back every deduction made in this transaction.
                        throw new AppError(
                            409,
                            `Insufficient stock for product ${item.productId}.`,
                            "INSUFFICIENT_STOCK"
                        );
                    }
                }
                return "CONFIRMED";
            });
        } catch (error) {
            // Two identical confirmations raced; the other one won and the transaction rolled back.
            if (error.code === "P2002") {
                status = "ALREADY_CONFIRMED";
            } else {
                throw error;
            }
        }

        res.status(200).json({ data: { orderId, status } });
    } catch (error) {
        next(error);
    }
}